using LibraryApi.Models;using LibraryApi.Repositories;using Microsoft.AspNetCore.Mvc;namespace LibraryApi.Controllers;[ApiController][Route("api/crud")]
public class CrudController(JsonBookRepository repo):ControllerBase{private bool Auth()=>Request.Headers.Authorization=="Bearer demo-library-token";[HttpGet("books")]public IActionResult All()=>Auth()?Ok(repo.All()):Unauthorized();[HttpGet("books/{id:int}")]public IActionResult One(int id)=>!Auth()?Unauthorized():repo.Get(id) is Book b?Ok(b):NotFound();[HttpPost("books")]public IActionResult Add(Book b)=>!Auth()?Unauthorized():Ok(repo.Add(b));[HttpPut("books/{id:int}")]public IActionResult Update(int id,Book b)=>!Auth()?Unauthorized():repo.Update(id,b)?Ok(b):NotFound();[HttpDelete("books/{id:int}")]public IActionResult Delete(int id)=>!Auth()?Unauthorized():repo.Delete(id)?NoContent():NotFound();}
